def transform(grid):
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    for r, row in enumerate(grid):
        colors = [v for v in row if v != bg]
        if not colors or row[0] == bg:
            continue
        color = Counter(colors).most_common(1)[0][0]
        last = max(c for c, v in enumerate(row) if v == color)
        if last < len(row) - 1:
            for c in range(last + 1, len(row)):
                out[r][c] = 1
    return out
